const join = (c = code) => {
  const raw = String(c ?? '');
  // v4.0: 链接 → 按访客提交该服务器到清单；邀请码 → 先当前服务器，无结果再跨服轮询。
  if (window.__SP_JOIN && typeof window.__SP_JOIN.looksLikeLink === 'function' && window.__SP_JOIN.looksLikeLink(raw)) {
    submitLink(raw.trim());
    return;
  }
  const k = normalizeCode(raw);
  if (!CODE_RE.test(k)) { toast(`同盟密钥为 ${ROOM_CODE_LEN} 位字母或数字`, 'warn'); return; }
  run('join', async () => {
    try {
      await net.request('room.join', { code: k });
    } catch (err) {
      // 当前服务器没有该房 → 轮询其他服务器（复用 shell-join.js 的跨服探测）
      if (!err || err.code !== 'ROOM_NOT_FOUND'
        || !window.__SP_JOIN || typeof window.__SP_JOIN.resolveCode !== 'function') throw err;
      const r = await window.__SP_JOIN.resolveCode(k);
      const hit = r && (r.kind === 'single' ? r.entry
        : r.kind === 'conflict' && Array.isArray(r.entries) ? r.entries[0] : null);
      if (hit && hit.id && window.shell && typeof window.shell.joinOnOrigin === 'function') {
        window.shell.joinOnOrigin(hit.id, k);
        return;
      }
      toast((r && r.note) || '未找到该同盟密钥对应的房间', 'warn');
    }
  });
};
const submitLink = (raw) => {
  toast('正在提交服务器…');
  setTimeout(() => {
    const p = window.__SP_JOIN && typeof window.__SP_JOIN.submitServerLink === 'function'
      ? window.__SP_JOIN.submitServerLink(raw)
      : Promise.resolve({ ok: false, text: '当前版本不支持提交，请到 dl.jiangjiangze.icu/servers 提交' });
    Promise.resolve(p).then((x) => {
      if (x && x.ok) toast(String(x.text || '已提交，审核通过后会出现在服务器列表'), 'success');
      else toast(String((x && x.text) || '提交失败，请稍后重试'), 'warn');
    }).catch(() => toast('提交失败，请稍后重试', 'warn'));
  }, 50);
};

/** 公开房间（v4.0）：大厅页左下角，风格与「加入同盟」区块一致；数据来自 window.__SP_LOBBY.rooms()，
 *  由 subscribeRooms 驱动更新（有订阅者且页面可见时 15s 轮询，见 extras/js/lobby.js）。 */
function PublicRooms({ onJoin }) {
  const [, setTick] = useState(0);
  useEffect(() => {
    const L = window.__SP_LOBBY;
    let unsub = null;
    if (L && typeof L.subscribeRooms === 'function') unsub = L.subscribeRooms(() => setTick((n) => n + 1));
    const id = setInterval(() => setTick((n) => n + 1), 1000);
    return () => { if (unsub) unsub(); clearInterval(id); };
  }, []);
  let rooms = [];
  try {
    rooms = window.__SP_LOBBY && typeof window.__SP_LOBBY.rooms === 'function' ? window.__SP_LOBBY.rooms() : [];
  } catch { rooms = []; }
  rooms = Array.isArray(rooms) ? rooms.slice(0, 8) : [];
  const left = (sec) => {
    const s = Math.max(0, Math.floor(Number(sec) || 0));
    return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
  };
  const rowStyle = 'display:flex;align-items:center;gap:8px;font-size:.13rem';
  return html`<div class="section-label"><span class="section-label__idx num">04</span>公开房间<${MicroLabel}>PUBLIC ROOMS<//></div>
    <${Panel} class="join-panel" tone="amber">
      ${rooms.length
        ? html`<div class="join-foot" style="display:flex;flex-direction:column;gap:4px">
            ${rooms.map((r) => html`<div key=${r.code} style=${rowStyle}>
              <b class="num" style="color:#4ed8af;min-width:2.6em">${r.code}</b>
              <span style="opacity:.8">${r.server || '—'}</span>
              <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;opacity:.55"
                title=${r.note}>${r.note || ''}</span>
              <span class="num" style=${'color:' + (r.left <= 60 ? '#e06c5a' : '#8a9a93')}>${r.left > 0 ? left(r.left) : '已过期'}</span>
              ${r.left > 0
                ? html`<${Button} variant="secondary" size="sm" onClick=${() => onJoin(r.code)}>加入<//>`
                : html`<${Button} variant="secondary" size="sm" disabled=${true}>已过期<//>`}
            </div>`)}
          </div>`
        : html`<div class="join-foot"><span class="t-dim">当前没有公开房间</span></div>`}
    <//>`;
}

